const detectServerEnv = () => {
	const hostname = window.location.hostname.toLowerCase();
	//alert(hostname)
	if (hostname.includes("localhost")) {
		return 22; // Force Dev2 mode when on localhost
	} else if (hostname.includes("cbsdev2")) {
		return 22;
	} else if (hostname.includes("cbsdev3")) {
		return 33;
	} else if (hostname.includes("webspace")) {
		return 10;
	} else {
		return 11; // Fallback to real-real
	}
};

