function generateOTP(anL) {
	// Declare a digits variable
	// which stores all digits
	let nL = 6;
	if (anL) {
		nL = anL;
	}
	var digits = '0123456789';
	let OTP = '';
	let aG = 0;
	for (let i = 0; i < nL; i++) {
		aG = Math.floor(Math.random() * 10);
		OTP += digits[Math.floor(Math.random() * 10)];
	}
	return OTP;
};

function generateLOTP(anL) {
	// Declare a string variable 
	// which stores all string  
	let nL = 6;
	if (anL) {
		nL = anL;
	}
	var string = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
	let OTP = '';

	// Find the length of string
	var len = string.length;
	for (let i = 0; i < nL; i++) {
		OTP += string[Math.floor(Math.random() * len)];
	}
	return OTP;
};

const aGetDateRef = (aERSuf) => {
	//axRunRun = ""
	let aNowDatev = new Date()
	let aYear2 = String(aNowDatev.getFullYear()).substring(2, 4);
	let aMonth2 = String(101 + aNowDatev.getMonth()).substring(1, 3);
	let aDate2 = String(100 + aNowDatev.getDate()).substring(1, 3);
	let aHour2 = String(100 + aNowDatev.getHours()).substring(1, 3);
	let aDateNow2 = aYear2 + aMonth2 + aDate2 + String(Date.now()).substring(5, 9) // 5,16
	//let aERCode = "5102300001"
	//let aERSuf = "F"
	//axRunRun = "ER" + aDateNow2
	return aERSuf + aDateNow2 //+ aYear2 + aMonth2 + aDate2 + aHour2;
}

const aGetBusYear = (aFM, aLM) => { // get Business year 
	let aNowDatev = new Date()
	let aCalYear = aNowDatev.getFullYear();
	let aCalMonth = aNowDatev.getMonth() + 1;
	if (aCalMonth >= aFM && aCalMonth <= aLM) {
		aCalYear = aCalYear - 1
	}
	return aCalYear;
}

const aNowText = () => {
	let aNowDatev = new Date()
	let aYear2 = String(aNowDatev.getFullYear());
	let aMonth2 = String(101 + aNowDatev.getMonth()).substring(1, 3);
	let aDate2 = String(100 + aNowDatev.getDate()).substring(1, 3);
	let aHour2 = String(100 + aNowDatev.getHours()).substring(1, 3);
	let aMinute2 = String(100 + aNowDatev.getMinutes()).substring(1, 3);
	let aSecond2 = String(100 + aNowDatev.getSeconds()).substring(1, 3);
	let aDateNow2 = aYear2 + "-" + aMonth2 + "-" + aDate2 + "T" + aHour2 + ":" + aMinute2 + ":" + aSecond2
	return aDateNow2;
}

