const aPopupHelp = (aHTitle, aHelpMessageOrFile, useFullScreen = false) => {
	const isPdf = typeof aHelpMessageOrFile === "string" && aHelpMessageOrFile.includes(".pdf");
	const isHtml = typeof aHelpMessageOrFile === "string" && aHelpMessageOrFile.includes(".html");
	const isPpt = typeof aHelpMessageOrFile === "string" && aHelpMessageOrFile.includes(".pptx");
	const isXlsx = typeof aHelpMessageOrFile === "string" && aHelpMessageOrFile.includes(".xlsx");

	const popup = $("#popupHelp").dxPopup({
		title: aHTitle,
		height: 750,
		width: 1200,
		position: { offset: "-40 -100" },
		fullScreen: useFullScreen,
		visible: true,
		showCloseButton: true,
		focusStateEnabled: false,
		toolbarItems: [
			{
				widget: "dxButton",
				location: "after",
				options: {
					icon: "fas fa-expand",
					onClick: function () {
						const currentState = popup.option("fullScreen");
						popup.option("fullScreen", !currentState);
					},
				},
			},
		],
		contentTemplate: function (contentElement) {
			const container = $("<div>").css({ height: "100%", overflowY: "auto" });

			if (isPdf || isHtml || isPpt) {
				const embedUrl = isPpt
					? `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(aHelpMessageOrFile)}`
					: aHelpMessageOrFile;

				const iframe = $("<iframe>")
					.attr("src", embedUrl)
					.css({ width: "100%", height: "100%", border: "none" });
				container.append(iframe);
			} else if (isXlsx) {
				// Use Microsoft Office Viewer for Excel files				
				const officeUrl = `https://view.officeapps.live.com/op/view.aspx?src=${encodeURIComponent(aHelpMessageOrFile)}`;
				const iframe = $("<iframe>")
					.attr("src", officeUrl)
					.css({ width: "100%", height: "100%", border: "none" });
				container.append(iframe);
			} else {
				container.append(aHelpMessageOrFile);
			}
			container.appendTo(contentElement);
		},
	}).dxPopup("instance");
};



function loadAndProcessSQLData(aDatabasea, aKeyField, aKeyIDa, axFieldSelected, callback) {
	var aVARs = {};
	var aArrays = {};
	var aObjects = {};

	loadSQLData(isLocalHost(), aDatabasea, aKeyIDa, aKeyField, axFieldSelected)
		.then(result => {
			if (!$.isArray(result)) {
				console.error("Unexpected result format:", result);
				return;
			}

			$.each(result, (index, item) => {
				let aMatch = item.TaskName.match(/\[(.*?)\]/);
				if (!aMatch) return;

				let taskProgram = item.TaskProgram.replace(/`/g, "'");

				if (item.TaskName.includes("{ARRAY}")) {
					aArrays[aMatch[1]] = parseArray(taskProgram);
				} else if (item.TaskName.includes("{T2O}")) {
					aObjects[aMatch[1]] = parseT2O(taskProgram);
				} else if (item.TaskName.includes("{OBJ}")) {
					aObjects[aMatch[1]] = parseObject(taskProgram);
				} else {
					aVARs[aMatch[1]] = parseVariable(taskProgram, item.TaskName);
				}
			});

			if (typeof callback === "function") {
				callback(aVARs, aArrays, aObjects);
			}
		})
		.fail(error => console.error("Error fetching SQL data:", error));
}

/** ✅ Function to parse ARRAY values */
function parseArray(data) {
	return data.split("\n")
		.map(line => $.trim(line))
		.map(line => (line === "" ? "" : isNaN(line) ? line : +line));
}

/** ✅ Function to parse T2O (Text to Object) */
function parseT2O(data) {
	return data.split("\n")
		.map(line => {
			line = $.trim(line).replace(/,$/, "");
			line = line.replace(/(\w+):/g, '"$1":').replace(/:\s*([\w]+)/g, ': "$1"');
			return JSON.parse(line);
		})
		.map(obj => {
			$.each(obj, (key, value) => {
				if (key.includes("amt") && typeof value === "string") {
					obj[key] = +value; // Convert numeric strings to numbers
				}
			});
			return obj;
		});
}

/** ✅ Function to parse OBJ (Object) */
function parseObject(data) {
	return data.split("\n").reduce((obj, line) => {
		let [key, value] = $.trim(line).split(":").map(part => $.trim(part));
		if (key && value !== undefined) obj[key] = isNaN(value) ? value : +value;
		return obj;
	}, {});
}

/** ✅ Function to parse simple variables */
function parseVariable(data, taskName) {
	return taskName.includes("{num}") ? +data : data;
}

// Export functions (For use in other scripts)
if (typeof module !== "undefined" && module.exports) {
	module.exports = { loadAndProcessSQLData };
}

